glsl3.vert:
precision highp float;
layout(std140) uniform CCGlobal {
  highp   vec4 cc_time;
  mediump vec4 cc_screenSize;
  mediump vec4 cc_nativeSize;
  mediump vec4 cc_probeInfo;
  mediump vec4 cc_debug_view_mode;
};
layout(std140) uniform CCCamera {
  highp   mat4 cc_matView;
  highp   mat4 cc_matViewInv;
  highp   mat4 cc_matProj;
  highp   mat4 cc_matProjInv;
  highp   mat4 cc_matViewProj;
  highp   mat4 cc_matViewProjInv;
  highp   vec4 cc_cameraPos;
  mediump vec4 cc_surfaceTransform;
  mediump vec4 cc_screenScale;
  mediump vec4 cc_exposure;
  mediump vec4 cc_mainLitDir;
  mediump vec4 cc_mainLitColor;
  mediump vec4 cc_ambientSky;
  mediump vec4 cc_ambientGround;
  mediump vec4 cc_fogColor;
  mediump vec4 cc_fogBase;
  mediump vec4 cc_fogAdd;
  mediump vec4 cc_nearFar;
  mediump vec4 cc_viewPort;
};
#if USE_LOCAL
  layout(std140) uniform CCLocal {
    highp mat4 cc_matWorld;
    highp mat4 cc_matWorldIT;
    highp vec4 cc_lightingMapUVParam;
    highp vec4 cc_localShadowBias;
    highp vec4 cc_reflectionProbeData1;
    highp vec4 cc_reflectionProbeData2;
    highp vec4 cc_reflectionProbeBlendData1;
    highp vec4 cc_reflectionProbeBlendData2;
  };
#endif
in vec3 a_position;
in vec2 a_texCoord;
in vec4 a_color;
out vec4 v_color;
out vec2 v_uv;
out vec2 v_localPos;
vec4 vert () {
  vec4 pos = vec4(a_position, 1);
  #if USE_LOCAL
    pos = cc_matWorld * pos;
  #endif
  pos = cc_matViewProj * pos;
  v_uv = a_texCoord;
  v_color = a_color;
  v_localPos = a_position.xy;
  return pos;
}
void main() { gl_Position = vert(); }

glsl3.frag:
precision highp float;
#if USE_ALPHA_TEST
  layout(std140) uniform ALPHA_TEST_DATA {
    float alphaThreshold;
  };
#endif
layout(std140) uniform CCGlobal {
  highp   vec4 cc_time;
  mediump vec4 cc_screenSize;
  mediump vec4 cc_nativeSize;
  mediump vec4 cc_probeInfo;
  mediump vec4 cc_debug_view_mode;
};
layout(std140) uniform CCCamera {
  highp   mat4 cc_matView;
  highp   mat4 cc_matViewInv;
  highp   mat4 cc_matProj;
  highp   mat4 cc_matProjInv;
  highp   mat4 cc_matViewProj;
  highp   mat4 cc_matViewProjInv;
  highp   vec4 cc_cameraPos;
  mediump vec4 cc_surfaceTransform;
  mediump vec4 cc_screenScale;
  mediump vec4 cc_exposure;
  mediump vec4 cc_mainLitDir;
  mediump vec4 cc_mainLitColor;
  mediump vec4 cc_ambientSky;
  mediump vec4 cc_ambientGround;
  mediump vec4 cc_fogColor;
  mediump vec4 cc_fogBase;
  mediump vec4 cc_fogAdd;
  mediump vec4 cc_nearFar;
  mediump vec4 cc_viewPort;
};
in vec4 v_color;
in vec2 v_uv;
in vec2 v_localPos;
uniform sampler2D cc_spriteTexture;
layout(std140) uniform LaserParams {
  vec4 glowColor;
  vec4 coreColor;
  float intensity;
  float speed;
  float glowRadius;
  float coreRadius;
  float glowIntensity;
  float coreIntensity;
  float turbulence;
  float noiseScale;
};
float noise(vec2 p) {
  return fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453);
}
float getGlow(float dist, float radius, float intensity) {
  return exp(-dist / radius) * intensity;
}
vec4 frag () {
    vec4 texColor = texture(cc_spriteTexture, v_uv);
    float time = cc_time.x;
    float distToCenter = abs(v_uv.x - 0.5) * 2.0;
    float coreGlow = getGlow(distToCenter, coreRadius, coreIntensity);
    float innerGlow = getGlow(distToCenter, glowRadius * 0.5, glowIntensity);
    float outerGlow = getGlow(distToCenter, glowRadius, glowIntensity * 0.5);
    float flow = 1.0;
    if (speed > 0.0) {
        flow = sin(v_uv.y * 6.0 - time * speed * 3.0) * 0.2 + 0.8;
    }
    float lengthFade = smoothstep(0.0, 0.3, v_uv.y) * (1.0 - smoothstep(0.7, 1.0, v_uv.y));
    if (turbulence > 0.0) {
        vec2 noiseCoord = vec2(v_uv.x * 2.0, v_uv.y * noiseScale + time * speed);
        float noiseValue = noise(noiseCoord) * 2.0 - 1.0;
        coreGlow *= (1.0 + noiseValue * turbulence * 0.3);
    }
    vec3 finalColor = vec3(0.0);
    finalColor += coreColor.rgb * coreGlow * 3.0;
    finalColor += glowColor.rgb * (innerGlow + outerGlow * 0.5);
    finalColor *= flow * lengthFade * intensity;
    float alpha = (coreGlow * 2.0 + innerGlow + outerGlow * 0.5);
    alpha *= flow * lengthFade * intensity * 0.8;
    alpha = clamp(alpha, 0.0, 1.0);
    alpha *= texColor.a * v_color.a;
    vec4 outputColor = vec4(finalColor * v_color.rgb, alpha);
    return outputColor;
}
layout(location = 0) out vec4 cc_FragColor;
void main() { cc_FragColor = frag(); }

